import{_ as d,o as r,c as e,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const S=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/SORT-CASES.md","filePath":"manual-zh/SORT-CASES.md","lastUpdated":1785684581000}'),s={name:"manual-zh/SORT-CASES.md"};function a(n,t,c,p,g,h){return r(),e("div",null,[...t[0]||(t[0]=[o(`<h3 id="_12-8-sort-cases" tabindex="-1">12.8 SORT CASES <a class="header-anchor" href="#_12-8-sort-cases" aria-label="Permalink to &quot;12.8 SORT CASES&quot;">​</a></h3><pre><code>SORT CASES BY var_list[({D|A}] [ var_list[({D|A}] ] ...
</code></pre><p><code>SORT CASES</code> 按一个或多个变量的值对活动数据集排序。</p><p>指定 <code>BY</code> 和要排序的变量列表。默认情况下，变量按升序排序。要覆盖排序顺序，可在变量列表之后指定 <code>(D)</code> 或 <code>(DOWN)</code> 得到降序，或指定 <code>(A)</code> 或 <code>(UP)</code> 得到升序。这些顺序对前面所列的所有变量生效，直到出现前一个 <code>(A)</code>、<code>(D)</code>、<code>(UP)</code> 或 <code>(DOWN)</code>。</p><p><code>SORT CASES</code> 使用的排序算法是稳定的。这意味着排序变量取值相同的记录，在排序前后保持相同的相对顺序。因此，对已排序的文件重新排序不会影响个案的顺序。</p><p><code>SORT CASES</code> 是一个过程。它会导致数据被读取。</p><p><code>SORT CASES</code> 尝试在内存中对整个活动数据集排序。如果工作区耗尽，它会回退到一种归并排序算法，该算法会创建大量临时文件。</p><p><code>SORT CASES</code> 不能出现在 <code>TEMPORARY</code> 之后。</p><h4 id="_12-8-1-排序示例" tabindex="-1">12.8.1 排序示例 <a class="header-anchor" href="#_12-8-1-排序示例" aria-label="Permalink to &quot;12.8.1 排序示例&quot;">​</a></h4><p>在示例 12.6 中，文件 physiology.sav 的数据按两个变量排序，即 <strong>sex</strong> 降序、<strong>temperature</strong> 升序。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get file=&#39;physiology.sav&#39;. sort cases by sex (D) temperature(A). list.</span></span></code></pre></div><p><strong>示例 12.6：</strong> 按两个变量对个案排序</p><p>在结果 12.4 中可以看到，所有 <strong>sex</strong> 为 ‘1’（女性）的个案都出现在 <strong>sex</strong> 为 ‘0’（男性）的个案之前。这是因为它们按降序排序。在每种性别内部，数据按 <strong>temperature</strong> 变量排序，这次是升序。</p><table tabindex="0"><thead><tr><th>sex</th><th>height</th><th>weight</th><th>temperature</th></tr></thead><tbody><tr><td>1</td><td>1606</td><td>56.1</td><td>34.56</td></tr><tr><td>1</td><td>179</td><td>56.3</td><td>35.15</td></tr><tr><td>1</td><td>1609</td><td>55.4</td><td>35.46</td></tr><tr><td>1</td><td>1606</td><td>56.0</td><td>36.06</td></tr><tr><td>1</td><td>1607</td><td>56.3</td><td>36.26</td></tr><tr><td>1</td><td>1604</td><td>56.0</td><td>36.57</td></tr><tr><td>1</td><td>1604</td><td>56.6</td><td>36.81</td></tr><tr><td>1</td><td>1606</td><td>56.3</td><td>36.88</td></tr><tr><td>1</td><td>1604</td><td>57.8</td><td>37.32</td></tr><tr><td>1</td><td>1598</td><td>55.6</td><td>37.37</td></tr><tr><td>1</td><td>1607</td><td>55.9</td><td>37.84</td></tr><tr><td>1</td><td>1605</td><td>54.5</td><td>37.86</td></tr><tr><td>1</td><td>1603</td><td>56.1</td><td>38.80</td></tr><tr><td>1</td><td>1604</td><td>58.1</td><td>38.85</td></tr><tr><td>1</td><td>1605</td><td>57.7</td><td>38.98</td></tr><tr><td>1</td><td>1709</td><td>55.6</td><td>39.45</td></tr><tr><td>1</td><td>1604</td><td>-55.6</td><td>39.72</td></tr><tr><td>1</td><td>1601</td><td>55.9</td><td>39.90</td></tr><tr><td>0</td><td>1799</td><td>90.3</td><td>32.59</td></tr><tr><td>0</td><td>1799</td><td>89.0</td><td>33.61</td></tr><tr><td>0</td><td>1799</td><td>90.6</td><td>34.04</td></tr><tr><td>0</td><td>1801</td><td>90.5</td><td>34.42</td></tr><tr><td>0</td><td>1802</td><td>87.7</td><td>35.03</td></tr><tr><td>0</td><td>1793</td><td>90.1</td><td>35.11</td></tr><tr><td>0</td><td>1801</td><td>92.1</td><td>35.98</td></tr><tr><td>0</td><td>1800</td><td>89.5</td><td>36.10</td></tr><tr><td>0</td><td>1645</td><td>92.1</td><td>36.68</td></tr><tr><td>0</td><td>1698</td><td>90.2</td><td>36.94</td></tr><tr><td>0</td><td>1800</td><td>89.6</td><td>37.02</td></tr><tr><td>0</td><td>1800</td><td>88.9</td><td>37.03</td></tr><tr><td>0</td><td>1801</td><td>88.9</td><td>37.12</td></tr><tr><td>0</td><td>1799</td><td>90.4</td><td>37.33</td></tr><tr><td>0</td><td>1903</td><td>91.5</td><td>37.52</td></tr><tr><td>0</td><td>1799</td><td>90.9</td><td>37.53</td></tr><tr><td>0</td><td>1800</td><td>91.0</td><td>37.60</td></tr><tr><td>0</td><td>1799</td><td>90.4</td><td>37.68</td></tr><tr><td>0</td><td>1801</td><td>91.7</td><td>38.98</td></tr><tr><td>0</td><td>1801</td><td>90.9</td><td>39.03</td></tr><tr><td>0</td><td>1799</td><td>89.3</td><td>39.77</td></tr><tr><td>0</td><td>1884</td><td>88.6</td><td>39.97</td></tr></tbody></table><p><strong>结果 12.4：</strong> 排序后的 physiology.sav 文件</p><p>请注意，<code>SORT CASES</code> 与所有其他转换一样，只影响活动文件。它对 physiology.sav 文件本身没有任何影响。要做到这一点，你必须使用 <code>SAVE</code> 命令重写该文件（参见 <a href="./SAVE">SAVE</a>）。</p><p>使用图形用户界面时，直接从数据视图执行排序通常更简单。为此，切换到数据视图。选择要按其排序的变量对应的列，单击按钮 1，然后单击按钮 3。将出现一个弹出菜单，如截图 12.5 所示。从该菜单中选择“升序排序”或“降序排序”。</p><p><strong>截图 12.5：</strong> 按单个变量 <strong>height</strong> 排序数据</p><p>不过，有时你会想按两个或更多变量排序，而用这种方法做不到。此时，你必须使用一些代码，或使用“数据”菜单中的“排序个案”对话框。截图 12.6 显示了设置为按 <strong>sex</strong> 和 <strong>height</strong> 两个变量执行排序的对话框。注意输入变量的顺序很重要。本例中，数据会先按 <strong>sex</strong> 排序，然后对所有 <strong>sex</strong> 相同的个案再按 <strong>height</strong> 排序。</p><p><strong>截图 12.6：</strong> 按两个变量 <strong>sex</strong> 和 <strong>height</strong> 排序数据</p>`,20)])])}const l=d(s,[["render",a]]);export{S as __pageData,l as default};
